-- Cross-schema worksheet endpoints require importer and diagnostic validation.
CREATE TABLE objective_plan_reconciliation (objective_id INTEGER PRIMARY KEY REFERENCES project_objective(objective_id), plan_objective_id VARCHAR NOT NULL UNIQUE, relation_type VARCHAR NOT NULL, record_status VARCHAR NOT NULL, basis VARCHAR NOT NULL, scope_note VARCHAR NOT NULL, prototype_text_at_mapping VARCHAR NOT NULL, source_text_at_mapping VARCHAR NOT NULL);
CREATE TABLE criterion_plan_reconciliation (criterion_id INTEGER PRIMARY KEY REFERENCES performance_criterion(criterion_id), plan_criterion_id VARCHAR NOT NULL UNIQUE, relation_type VARCHAR NOT NULL, record_status VARCHAR NOT NULL, basis VARCHAR NOT NULL, scope_note VARCHAR NOT NULL, prototype_text_at_mapping VARCHAR NOT NULL, source_text_at_mapping VARCHAR NOT NULL);
CREATE VIEW plan_reconciliation_issues AS SELECT 'objective endpoint or wording changed' AS issue,m.plan_objective_id AS local_id FROM objective_plan_reconciliation m JOIN project_objective o ON o.objective_id=m.objective_id LEFT JOIN research_register.plan_objective p ON p.objective_id=m.plan_objective_id WHERE p.objective_id IS NULL OR o.objective_text<>m.prototype_text_at_mapping OR p.normalized_text<>m.source_text_at_mapping UNION ALL SELECT 'criterion endpoint or wording changed',m.plan_criterion_id FROM criterion_plan_reconciliation m JOIN performance_criterion c ON c.criterion_id=m.criterion_id LEFT JOIN research_register.plan_criterion p ON p.criterion_id=m.plan_criterion_id WHERE p.criterion_id IS NULL OR c.criterion_text<>m.prototype_text_at_mapping OR p.summary<>m.source_text_at_mapping;
CREATE VIEW plan_objective_comparison AS SELECT m.objective_id,m.plan_objective_id,m.relation_type,m.record_status,m.basis,m.scope_note,o.objective_text AS prototype_text,p.normalized_text AS worksheet_text FROM objective_plan_reconciliation m JOIN project_objective o ON o.objective_id=m.objective_id JOIN research_register.plan_objective p ON p.objective_id=m.plan_objective_id;
CREATE VIEW plan_criterion_comparison AS SELECT m.criterion_id,m.plan_criterion_id,m.relation_type,m.record_status,m.basis,m.scope_note,c.criterion_text AS prototype_text,p.summary AS worksheet_text,p.scope_note AS worksheet_scope FROM criterion_plan_reconciliation m JOIN performance_criterion c ON c.criterion_id=m.criterion_id JOIN research_register.plan_criterion p ON p.criterion_id=m.plan_criterion_id;
